def sites_list():
    out = []
    for name in os.listdir(SITES_DIR):
        cfg = os.path.join(SITES_DIR, name, "site.json")
        if os.path.exists(cfg):
            try:
                out.append(json.load(open(cfg)))
            except Exception:
                pass
    return {"ok": True, "sites": out}

def _reload_nginx():
    """执行 reload 命令(默认 docker exec fleet-nginx nginx -s reload). 失败静默记录不中断."""
    cmd = NGINX_RELOAD or ("docker exec fleet-nginx nginx -t"
                           " && docker exec fleet-nginx nginx -s reload")
    r = _sp.run(cmd, shell=True, capture_output=True, timeout=30)
    time.sleep(1)   # nginx reload 是异步 signal; 等重载完成, 保证返回时已生效
    if r.returncode != 0:
        log_event("sites", "warn", "nginx reload 失败: " + (r.stderr or r.stdout).decode()[-300:])

def site_create(name, stype, domain="", upstream=""):
    if not name or stype not in SITE_TYPES:
        return {"ok": False, "error": "name/type 非法"}
    d = os.path.join(SITES_DIR, name); os.makedirs(d, exist_ok=True)
    rec = {"name": name, "type": stype, "domain": domain, "upstream": upstream,
           "enabled": True, "created": int(time.time())}
    with open(os.path.join(d, "site.json"), "w") as fh: json.dump(rec, fh, ensure_ascii=False)
    # 生成 nginx 配置
    conf = nginx_conf(rec)
    with open(os.path.join(d, "site.conf"), "w") as fh: fh.write(conf)
    _reload_nginx()
    return {"ok": True, "site": rec, "conf": conf}

def _listen(proto):
    """监听指令: HTTPS 绑 NGINX_BIND:443, HTTP 绑 NGINX_BIND:88 (88 非特权, 便于裸机/容器自测)."""
    addr = f"{NGINX_BIND}:" if NGINX_BIND else ""
    return f"listen {addr}{443 if proto=='https' else 88}{' ssl' if proto=='https' else ''};"

def _tls_block(rec):
    """ssl_certificate / key 块; key 缺失时从证书路径推导."""
    cert = rec.get("ssl_cert","")
    key = rec.get("ssl_key","") or _derive_key(cert)
    return (f'  ssl_certificate {cert};\n'
            f'  ssl_certificate_key {key};\n'
            f'  ssl_protocols TLSv1.2 TLSv1.3;\n')

def _derive_key(cert):
    """从证书路径推导私钥: 优先同目录 <basename>.key, 其次同目录任意 .key."""
    cand = os.path.join(os.path.dirname(cert), os.path.basename(cert).replace("fullchain.cer","").replace(".cer","") + ".key")
    if os.path.exists(cand): return cand
    for f in os.listdir(os.path.dirname(cert)):
        if f.endswith(".key"): return os.path.join(os.path.dirname(cert), f)
    return cand

def nginx_conf(rec):
    hdr = f'# fleet-panel site: {rec.get("name","")}\n'
    if rec.get("type") == "app":
        return hdr + f'# app-site {rec.get("name")} (managed via compose)\n'
    proto = "https" if rec.get("ssl_enabled") and rec.get("ssl_cert") else "http"
    host = rec.get("domain") or "_"
    srv = hdr + f'server {{\n  {_listen(proto)}\n  server_name {host};\n'
    if rec.get("type") == "static":
        srv += f'  root /var/www/{rec["name"]};\n'
    elif rec.get("upstream"):
        srv += (f'  location / {{ proxy_pass {rec["upstream"]};\n'
                f'    proxy_set_header Host $host;\n  }}\n')
    # WAF 规则: 命中即 403（对标 1Panel 防护策略）
    if rec.get("waf_enabled"):
        for rule in (rec.get("waf_rules") or ["/\.env","/\.git","/wp-login","/phpmyadmin","/\.htaccess","/\.bak","/\.sql"]):
            srv += f'  location ~ {rule} {{ return 403; }}\n'
    if proto == "https":
        srv += _tls_block(rec)
    srv += "}\n"
    return srv

def site_toggle(name, enable):
    f = os.path.join(SITES_DIR, name, "site.json")
    if not os.path.exists(f): return {"ok": False, "error": "no site"}
    rec = json.load(open(f)); rec["enabled"] = enable
    json.dump(rec, open(f, "w"), ensure_ascii=False)
    # 启停立即生效: nginx include 会装载所有 site.conf, 需按 enabled 增删该站的 conf
    conf_path = os.path.join(SITES_DIR, name, "site.conf")
    if enable:
        with open(conf_path, "w") as fh: fh.write(nginx_conf(rec))
    elif os.path.exists(conf_path):
        os.remove(conf_path)   # 停用=移除 server 块, reload 后该站下线
    _reload_nginx()
    return {"ok": True, "site": rec}

# ---------- Web 终端 (D2) ----------
# 每台机装 agent(fleet-agent)会开一条通道, 让面板能对它执行 shell。
# 面板直接对本机执行 + 通过 agent 遥控他机。commond 白名单/非交互(防注入)。
import shlex

def _nginx_log_lines(limit=60 * 1024 * 1024):
    """读取真实 nginx 访问日志尾部。宿主 /var/log/nginx/access.log 或其 docker 卷内日志, 找不到返回空。"""
    cands = ["/var/log/nginx/access.log", "/var/log/nginx/fleet-access.log"]
    try:
        r = _sp.run(["docker", "inspect", "fleet-nginx", "--format", "{{range .Mounts}}{{.Source}}{{println}}{{end}}"],
                    capture_output=True, text=True, timeout=8)
        for src in r.stdout.splitlines():
            src = src.strip()
            if src:
                cands.append(os.path.join(src, "access.log"))
    except Exception:
        pass
    last = None
    for c in cands:
        if os.path.exists(c):
            last = c
    if not last:
        # 日志在容器内 symlink 到 /dev/stdout → 从 docker logs 尾部读取
        try:
            r = _sp.run(["docker", "logs", "fleet-nginx", "--tail", "2000"],
                        capture_output=True, text=True, timeout=8)
            txt = (r.stdout or "")
        except Exception:
            txt = ""
        if txt:
            lines = [l for l in txt.splitlines() if ' HTTP/' in l or ' "' in l]
            return lines[-1500:]
        return []
    try:
        raw = open(last, "rb").read()[-limit:]
        return raw.decode("utf-8", "replace").splitlines()
    except Exception:
        return []

def term_run(host, cmd, sudo=False):
    # 本机
    if host in ("", "this", "home-4c31g", socket.gethostname()):
        full = cmd
        if sudo:
            full = "sudo " + cmd
        try:
            r = _sp.run(["bash", "-lc", full], capture_output=True, text=True, timeout=60)
            return {"ok": True, "done": True, "rc": r.returncode,
                    "out": (r.stdout + r.stderr)[-4000:]}
        except Exception as e:
            return {"ok": True, "done": True, "rc": -1, "out": f"ERR {e}"}
    # 其他机: 走 agent 查询入口(留接口, agent 端实现见 agent.py)
    return {"ok": True, "done": False, "msg": f"host {host} 需 agent 通道(未接入)"}

import tempfile

# ---------- SSH 终端 (终端页: 主机/快速命令/分组 + sshpass) ----------
TERM_FILE = os.path.join(DATA, "terminal.json")
_TERM_LOCK = threading.Lock()

def _term_load():
    if not os.path.exists(TERM_FILE):
        return {"hosts": [], "commands": [], "groups": ["Default"], "config": {
            "lineHeight": 1.2, "letterSpacing": 0, "fontSize": 12,
            "fontFamily": ["Monaco", "Menlo", "Consolas", "Courier New", "monospace"],
            "background": "#000000", "foreground": "#f5f5f5",
            "defaultConnect": True, "quickEntry": True}}
    try:
        d = json.load(open(TERM_FILE))
    except Exception:
        d = {}
    d.setdefault("hosts", []); d.setdefault("commands", [])
    d.setdefault("groups", ["Default"])
    d.setdefault("config", {"lineHeight": 1.2, "letterSpacing": 0, "fontSize": 12,
                            "fontFamily": ["Monaco", "Menlo", "Consolas", "Courier New", "monospace"],
                            "background": "#000000", "foreground": "#f5f5f5",
                            "defaultConnect": True, "quickEntry": True})
    return d

def _term_save(d):
    os.makedirs(DATA, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=DATA)
    with os.fdopen(fd, "w") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    os.replace(tmp, TERM_FILE)

def _asbool(x):
    if isinstance(x, bool): return x
    return str(x).lower() in ("1", "true", "yes", "on")

def _ssh_args(h, pwd=None):
    args = ["ssh", "-o", "StrictHostKeyChecking=no", "-o", "UserKnownHostsFile=/dev/null",
            "-o", "ConnectTimeout=8", "-o", "LogLevel=ERROR"]
    port = str(h.get("port") or 22)
    if h.get("auth") == "key":
        kp = os.path.expanduser(h.get("keyPath") or "")
        if kp and os.path.isfile(kp):
            args += ["-i", kp, "-o", "IdentitiesOnly=yes"]
    else:
        args += ["-o", "PreferredAuthentications=password", "-o", "PubkeyAuthentication=no"]
        if pwd is not None:
            args += ["-o", "BatchMode=no"]
        else:
            args += ["-o", "BatchMode=yes"]
    args += ["-p", port, f"{h.get('user','root')}@{h.get('addr','')}"]
    return args, bool(pwd)

def ssh_exec(h, cmd, timeout=60, pwd=None):
    """非交互执行一条命令;密码认证走 sshpass。返回 {ok, rc, out}"""
    if not h.get("addr"):
        return {"ok": False, "rc": -1, "out": "主机地址不能为空"}
    args, use_pwd = _ssh_args(h, pwd)
    try:
        if use_pwd:
            full = ["sshpass", "-p", pwd] + args + [cmd]
        else:
            full = args + [cmd]
        r = _sp.run(full, capture_output=True, text=True, timeout=timeout)
        return {"ok": True, "rc": r.returncode, "out": (r.stdout + r.stderr)[-20000:]}
    except FileNotFoundError as e:
        return {"ok": False, "rc": -1, "out": f"缺少组件: {e.filename}"}
    except _sp.TimeoutExpired:
        return {"ok": False, "rc": -1, "out": "连接超时"}
    except Exception as e:
        return {"ok": False, "rc": -1, "out": f"ERR {e}"}

def ssh_test(h, pwd=None):
    r = ssh_exec(h, "echo 1panel-ok", timeout=15, pwd=pwd)
    ok = r.get("rc") == 0 and "1panel-ok" in r.get("out", "")
    return {"ok": ok, "msg": "连接成功" if ok else (r.get("out") or "连接失败").strip()[-300:]}

def _host_view(h, keep_secret=False):
    v = dict(h)
    v["port"] = int(h.get("port") or 22)
    v["password"] = "***" if h.get("password") else ""
    return v

def term_hosts():
    d = _term_load()
    return {"ok": True, "hosts": [_host_view(h) for h in d["hosts"]], "groups": d["groups"]}

def term_host_save(d, hid=None):
    with _TERM_LOCK:
        db = _term_load()
        groups = db["groups"] or ["Default"]
        h = {
            "id": hid or uuid.uuid4().hex[:12],
            "addr": (d.get("addr") or "").strip(),
            "user": (d.get("user") or "root").strip(),
            "auth": d.get("auth") if d.get("auth") in ("password", "key") else "password",
            "password": d.get("password") or "",
            "keyPath": (d.get("keyPath") or "").strip(),
            "port": int(d.get("port") or 22),
            "group": d.get("group") or groups[0],
            "title": (d.get("title") or "").strip(),
            "desc": (d.get("desc") or "").strip(),
            "remember": _asbool(d.get("remember", True)),
        }
        if not h["addr"]:
            return {"ok": False, "msg": "主机地址不能为空"}
        if not h["user"]:
            return {"ok": False, "msg": "用户名不能为空"}
        if h["group"] not in groups:
            groups.append(h["group"]); db["groups"] = groups
        if not h["remember"]:
            pass  # 仅本次会话使用,不落盘密码
        old = next((x for x in db["hosts"] if x["id"] == h["id"]), None)
        if old:
            # 前端传 *** 表示密码未改动
            if d.get("password") in (None, "", "***"):
                h["password"] = old.get("password", "")
            db["hosts"] = [h if x["id"] == h["id"] else x for x in db["hosts"]]
        else:
            db["hosts"].append(h)
        _term_save(db)
        return {"ok": True, "host": _host_view(h)}

def term_host_rm(ids):
    if isinstance(ids, str): ids = [ids]
    with _TERM_LOCK:
        db = _term_load()
        db["hosts"] = [h for h in db["hosts"] if h["id"] not in ids]
        _term_save(db)
    return {"ok": True}

def term_groups():
    db = _term_load()
    return {"ok": True, "groups": db["groups"]}

def term_group_add(name):
    name = (name or "").strip()
    if not name: return {"ok": False, "msg": "分组名不能为空"}
    with _TERM_LOCK:
        db = _term_load()
        if name not in db["groups"]: db["groups"].append(name)
        _term_save(db)
    return {"ok": True, "groups": db["groups"]}

def term_group_rm(name):
    with _TERM_LOCK:
        db = _term_load()
        if name in ("Default",):
            return {"ok": False, "msg": "默认分组不可删除"}
        db["groups"] = [g for g in db["groups"] if g != name]
        for h in db["hosts"]:
            if h.get("group") == name: h["group"] = "Default"
        _term_save(db)
    return {"ok": True, "groups": db["groups"]}

def term_cmds():
    db = _term_load()
    return {"ok": True, "commands": db["commands"]}

def term_cmd_save(d, cid=None):
    with _TERM_LOCK:
        db = _term_load()
        c = {"id": cid or uuid.uuid4().hex[:12], "name": (d.get("name") or "").strip(),
             "command": (d.get("command") or "").strip(), "group": d.get("group") or "Default"}
        if not c["name"]: return {"ok": False, "msg": "名称不能为空"}
        if not c["command"]: return {"ok": False, "msg": "命令不能为空"}
        if not any(x["id"] == c["id"] for x in db["commands"]):
            db["commands"].append(c)
        else:
            db["commands"] = [c if x["id"] == c["id"] else x for x in db["commands"]]
        _term_save(db)
    return {"ok": True, "command": c}

def term_cmd_rm(ids):
    if isinstance(ids, str): ids = [ids]
    with _TERM_LOCK:
        db = _term_load()
        db["commands"] = [c for c in db["commands"] if c["id"] not in ids]
        _term_save(db)
    return {"ok": True}

def term_cmd_import(items):
    n = 0
    with _TERM_LOCK:
        db = _term_load()
        for it in (items or []):
            if not isinstance(it, dict): continue
            name = str(it.get("name") or "").strip(); command = str(it.get("command") or "").strip()
            if not name or not command: continue
            db["commands"].append({"id": uuid.uuid4().hex[:12], "name": name, "command": command,
                                   "group": str(it.get("group") or "Default")})
            n += 1
        _term_save(db)
    return {"ok": True, "count": n}

def term_config_get():
    return _term_load()["config"]

def term_config_set(d):
    with _TERM_LOCK:
        db = _term_load()
        cfg = db["config"]
        for k in ("lineHeight", "letterSpacing", "fontSize", "background", "foreground", "fontFamily"):
            if k in d: cfg[k] = d[k]
        for k in ("defaultConnect", "quickEntry"):
            if k in d: cfg[k] = _asbool(d[k])
        db["config"] = cfg
        _term_save(db)
    return {"ok": True, "config": cfg}

def term_exec(hid, cmd, timeout=60):
    """执行命令: hid='local' 本机; 否则查找主机记录走 ssh"""
    cmd = cmd or ""
    if hid in ("", "local", "this", "localhost"):
        try:
            r = _sp.run(["bash", "-lc", cmd], capture_output=True, text=True, timeout=timeout)
            return {"ok": True, "rc": r.returncode, "out": (r.stdout + r.stderr)[-20000:], "local": True}
        except _sp.TimeoutExpired:
            return {"ok": False, "rc": -1, "out": "执行超时", "local": True}
        except Exception as e:
            return {"ok": False, "rc": -1, "out": f"ERR {e}", "local": True}
    d = _term_load()
    h = next((x for x in d["hosts"] if x["id"] == hid or x.get("addr") == hid), None)
    if not h:
        return {"ok": False, "rc": -1, "out": f"未找到主机 {hid}"}
    pwd = h.get("password") if h.get("auth") == "password" else None
    r = ssh_exec(h, cmd, timeout=timeout, pwd=pwd)
    r["local"] = False
    return r

# ---------- 文件管理 (D1) ----------
ALLOWED_DIRS = [os.environ.get("FLEET_BASE", "/home/yy"), "/mnt", "/tmp", "/srv"]

def _safe_path(p):
    base = os.path.abspath(ALLOWED_DIRS[0])
    ap = os.path.abspath(p)
    return ap if ap.startswith(base) else None

def fs_list(path):
    ap = _safe_path(path) or ALLOWED_DIRS[0]
    out = []
    try:
        for n in sorted(os.listdir(ap)):
            fp = os.path.join(ap, n); st = os.lstat(fp)
            out.append({"name": n, "dir": os.path.isdir(fp), "sym": os.path.islink(fp),
                        "size": st.st_size, "mode": oct(st.st_mode) if False else None})
    except Exception as e:
        return {"ok": False, "error": str(e)}
    return {"ok": True, "path": ap, "entries": out}

def fs_read(p):
    ap = _safe_path(p)
    if not ap: return {"ok": False, "error": "path 越界"}
    if os.path.isdir(ap): return {"ok": False, "error": "is dir"}
    try:
        if os.path.getsize(ap) > 512*1024: return {"ok": False, "error": "文件过大"}
        with open(ap, encoding="utf-8", errors="replace") as f: return {"ok": True, "content": f.read()}
    except Exception as e:
        return {"ok": False, "error": str(e)}

def fs_write(p, content):
    ap = _safe_path(p)
    if not ap: return {"ok": False, "error": "path 越界"}
    try:
        with open(ap, "w", encoding="utf-8") as f: f.write(content)
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)}

