    out=[]
    for f in sorted(glob.glob(DATA+"/backups/*"), reverse=True):
        st=os.stat(f); out.append({"file": os.path.basename(f), "size": st.st_size, "mtime": int(st.st_mtime)})
    return {"ok": True, "backups": out[:50]}

