def _session_user(headers):
    # Authorization: Bearer 优先——即真正的登录会话 token，也接受 APITOKEN（agent/CLI 单 token 模式）
    tok = (headers.get("Authorization") or "").replace("Bearer ", "")
    if tok in SESS: return SESS[tok]
    if tok == APITOKEN: return "admin"
    # 浏览器端走 X-Fleet-Token = 会话 token；此处只认真实会话，不回退到 APITOKEN，
    # 否则登录页未登录也能靠前端写死的 TOK 直接当 admin 进入
    tok = headers.get("X-Fleet-Token") or ""
    if tok in SESS: return SESS[tok]
    return None
def _can_write(headers):
    who = _session_user(headers)
    if not who: return None
    role = _load_users().get(who, {}).get("role", "viewer")
    return None if role == "viewer" else who   # viewer 只读

