ALERT_FILE = DATA + "/alert.json"
def _load_alert():
    if not os.path.exists(ALERT_FILE):
        a = {"thresholds": dict(THRESH), "channels": {"webhook": NOTIFY["webhook"], "mail": NOTIFY["mail"]},
             "enabled": {"webhook": bool(NOTIFY["webhook"]), "mail": bool(NOTIFY["mail"])}}
        _save_alert(a); return a
    try: return json.load(open(ALERT_FILE))
    except Exception: return {"thresholds": dict(THRESH), "channels": {}, "enabled": {}}
def _save_alert(a): json.dump(a, open(ALERT_FILE,"w"), ensure_ascii=False, indent=2)
def alert_get(): return {"ok": True, "alert": _load_alert()}
def alert_set(patch):
    a = _load_alert()
    if "thresholds" in patch:
        a["thresholds"].update(patch["thresholds"])
    if "channels" in patch: a["channels"].update({k: v for k, v in patch["channels"].items()})
    if "enabled" in patch: a["enabled"].update({k: bool(v) for k, v in patch["enabled"].items()})
    _save_alert(a); _audit("info", "admin", "更新告警通知配置", source="alert", operate="edit", detail_en="Update alert notification"); return {"ok": True, "alert": a}

def _send_chan(chan, cfg, sev, host, msg):
    """通知插件: webhook / dingtalk / wechat(企业微信) / mail。返回 ok,err。"""
    text = f"[{sev}] {host}: {msg}"
    if chan == "webhook" and cfg:
        try:
            import urllib.request
            urllib.request.urlopen(urllib.request.Request(cfg, data=json.dumps({"msg_type":"text",
                "content":{"text":text}}).encode(), headers={"Content-Type":"application/json"}), timeout=6).read()
            return True, ""
        except Exception as e: return False, str(e)
    if chan == "dingtalk" and cfg:
        try:
            import urllib.request
            urllib.request.urlopen(urllib.request.Request(cfg, data=json.dumps({"msgtype":"text",
                "text":{"content":text}}).encode(), headers={"Content-Type":"application/json"}), timeout=6).read()
            return True, ""
        except Exception as e: return False, str(e)
    if chan == "wechat" and cfg:
        try:
            import urllib.request
            urllib.request.urlopen(urllib.request.Request(cfg, data=json.dumps({"msgtype":"text",
                "text":{"content":text}}).encode(), headers={"Content-Type":"application/json"}), timeout=6).read()
            return True, ""
        except Exception as e: return False, str(e)
    if chan == "mail" and cfg:
        # cfg 形如 smtp://user:pass@host:port?to=a@b.c ; 简单 smtplib
        try:
            import smtplib
            cfg = cfg.replace("smtp://", "")
            auth, rest = cfg.split("@", 1); user, pwd = auth.split(":", 1); host, port = rest.split(":", 1)
            to = cfg.split("to=")[-1]
            s = smtplib.SMTP(host, int(port.split("?")[0])); s.starttls(); s.login(user, pwd)
            s.sendmail(user, to, f"Subject: fleet alert\n\n{text}".encode()); s.quit()
            return True, ""
        except Exception as e: return False, str(e)
    return False, "channel disabled/no cfg"

def notify_ex(sev, host, msg):
    """走线上告警策略里的通道。"""
    a = _load_alert()
    enabled = a.get("enabled", {}); chans = a.get("channels", {})
    for chan, on in enabled.items():
        if on:
            ok, err = _send_chan(chan, chans.get(chan, ""), sev, host, msg)
            if not ok: log_event(host, sev, f"channel {chan} fail: {err}")
    print(f"[NOTIFY][{sev}] {host}: {msg}", flush=True)

