_conn = threading.local()

def db():
    if not getattr(_conn, "c", None):
        c = sqlite3.connect(DB)
        c.execute("PRAGMA journal_mode=WAL")
        c.execute("""CREATE TABLE IF NOT EXISTS hosts(
            name TEXT PRIMARY KEY, ip TEXT, inet TEXT,
            loaded REAL, mem REAL, disk REAL, docker INTEGER, latency REAL,
            load_ok INTEGER, mem_ok INTEGER, disk_ok INTEGER, latency_ok INTEGER,
            alerts INTEGER, sev TEXT, at INTEGER)""")
        c.execute("""CREATE TABLE IF NOT EXISTS cmds(
            id INTEGER PRIMARY KEY AUTOINCREMENT, host TEXT, proc TEXT, cmd TEXT,
            status TEXT, issued_at INTEGER, done_at INTEGER, result TEXT)""")
        c.execute("""CREATE TABLE IF NOT EXISTS events(
            id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER, host TEXT, level TEXT, msg TEXT)""")
        _conn.c = c
    return _conn.c

def log_event(host, level, msg):
    c = db()
    c.execute("INSERT INTO events(at,host,level,msg) VALUES(?,?,?,?)",
              (int(time.time()), host, level, msg))
    c.commit()

def fmt_bytes(b):
    if b >= 1024**4: return f"{b/1024**4:.2f} TB"
    if b >= 1024**3: return f"{b/1024**3:.2f} GB"
    if b >= 1024**2: return f"{b/1024**2:.1f} MB"
    return f"{b/1024:.1f} KB"

# ---------- 通知 ----------
def notify(sev, host, msg):
    log_event(host, sev, f"NOTIFY {msg}")
    w = NOTIFY["webhook"]
    if w and w.startswith("http"):
        try:
            import urllib.request
            req = urllib.request.Request(w, data=json.dumps({"msg_type":"text",
                "content":{"text":f"[{sev}] {host}: {msg}"}}).encode(),
                headers={"Content-Type":"application/json"})
            urllib.request.urlopen(req, timeout=6).read()
        except Exception as e:
            log_event(host, sev, f"webhook fail: {e}")
    print(f"[NOTIFY][{sev}] {host}: {msg}", flush=True)

# ---------- agent 上报 ----------
def _auth(h):
    if h.get("X-Fleet-Token") == APITOKEN: return True
    return _session_user(h) is not None   # 已登录(Authorization Bearer session)也算已认证

def report(host, ip, inet, metrics):
    load1 = float(metrics.get("load1", 0)); mem = float(metrics.get("mem", 0))
    disk = float(metrics.get("disk", 0)); docker = int(metrics.get("docker", 0))
    lat = float(metrics.get("latency", 0))
    th = _load_alert().get("thresholds", THRESH)
    lk = 1 if load1 < th["load1"] else 0
    mk = 1 if mem   < th["mem"]   else 0
    dk = 1 if disk  < th["disk"]  else 0
    wk = 1 if lat   < th["latency_ms"] else 0
    alerts = (1-lk)+(1-mk)+(1-dk)+(1-wk)
    sev = "ok" if alerts==0 else ("warn" if alerts<=2 else "crit")
    c = db()
    c.execute("""INSERT INTO hosts(name,ip,inet,loaded,mem,disk,docker,latency,
                 load_ok,mem_ok,disk_ok,latency_ok,alerts,sev,at)
                 VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                 ON CONFLICT(name) DO UPDATE SET
                 ip=excluded.ip,inet=excluded.inet,loaded=excluded.loaded,mem=excluded.mem,
                 disk=excluded.disk,docker=excluded.docker,latency=excluded.latency,
                 load_ok=excluded.load_ok,mem_ok=excluded.mem_ok,disk_ok=excluded.disk_ok,
                 latency_ok=excluded.latency_ok,alerts=excluded.alerts,sev=excluded.sev,at=excluded.at""",
              (host, ip, inet, load1, mem, disk, docker, lat, lk, mk, dk, wk, alerts, sev, int(time.time())))
    if alerts:
        parts = []
        if not lk: parts.append(f"load={load1}")
        if not mk: parts.append(f"mem={mem}%")
        if not dk: parts.append(f"disk={disk}%")
        if not wk: parts.append(f"latency={lat}ms")
        notify_ex(sev, host, "alert: " + ", ".join(parts))
    # 静默 —— 快速恢复,避免重复轰炸
    c.execute("DELETE FROM events WHERE at < ?", (int(time.time())-86400,))
    c.commit()
    return {"ok": True, "sev": sev, "alerts": alerts}

# ---------- Flask ----------
def make_app():
    def platform_machine_kernel(arch_only=False):
        import platform as _pl
        try:
            if arch_only: return _pl.machine()
            return _pl.release()
        except Exception:
            return ""
    from flask import Flask, request, jsonify, render_template_string, Response
    app = Flask(__name__)
    app.config["JSON_AS_ASCII"] = False

    def need_auth():
        return _auth(request.headers)

    @app.get("/")
    def index():
        return render_template_string(HTML, SESSION_TOKEN=APITOKEN)

    @app.post("/api/agent/report")
    def api_report():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        if "host" not in d: return jsonify({"error":"need host"}), 400
        try:
            return jsonify(report(d["host"], d.get("ip",""), d.get("inet",""), d))
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @app.get("/api/agents")
    def api_agents():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """智能体列表(对标本机 1Panel「智能体」)。"""
        return jsonify({"list": _col("agents")})

    @app.post("/api/agents")
    def api_agents_add():
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        d.setdefault("typ", "Archetype"); d.setdefault("sev", "ok"); d.setdefault("status", "正常")
        d["time"] = time.strftime("%Y-%m-%d %H:%M:%S")
        return jsonify(col_add("agents", d))

    @app.post("/api/agents/<name>/rm")
    def api_agents_rm(name):
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        return jsonify(col_rm("agents", "name", name))

    @app.post("/api/agents/<name>/edit")
    def api_agents_edit(name):
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        rows = _col("agents")
        for r in rows:
            if r.get("name") == name:
                if d.get("name") and d["name"] != name and any(x.get("name") == d["name"] for x in rows):
                    return jsonify({"error": "same name exists"}), 400
                for k, v in d.items():
                    if v is not None: r[k] = v
                r["time"] = time.strftime("%Y-%m-%d %H:%M:%S")
                _save_col("agents", rows)
                _audit("info", "admin", f"编辑智能体 [{name}]", source="agents", operate="edit", detail_en=f"Edit agent [{name}]")
                return jsonify(r)
        return jsonify({"error": "not found"}), 404

    @app.get("/api/local-models")
    def api_local_models():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """本地模型(对标本机「模型」-「本地模型」): 真实探测本机 ollama/vllm 及已加载模型。
        空环境返回空列表, 前端渲染"暂无数据 / 未检测到本地推理服务"。"""
        out = []
        try:
            r = _sp.run(["bash", "-lc", "command -v ollama && ollama list 2>/dev/null"],
                        capture_output=True, text=True, timeout=15)
            if not r.returncode:
                for ln in r.stdout.splitlines():
                    p = ln.split()
                    if len(p) >= 4 and p[0] != "NAME":
                        out.append({"name": p[0], "size": p[-3] + " " + p[-2], "modified": p[-1], "vendor": "ollama"})
        except Exception:
            pass
        try:
            r = _sp.run(["bash", "-lc", "command -v vllm && vllm --version 2>/dev/null | head -1"],
                        capture_output=True, text=True, timeout=15)
            if not r.returncode and r.stdout.strip():
                out.append({"name": "vllm", "size": "", "modified": "", "vendor": "vllm",
                            "ver": r.stdout.strip()})
        except Exception:
            pass
        return jsonify({"list": out})

