    def _cpu_pct_recent():
        try:
            parts = open("/proc/stat").readline().split()
            t1 = sum(int(v) for v in parts[1:]); i1 = int(parts[4])
            time.sleep(0.25)
            parts = open("/proc/stat").readline().split()
            t2 = sum(int(v) for v in parts[1:]); i2 = int(parts[4])
            return [round(100 * (1 - (i2 - i1) / max(1, t2 - t1)), 1)]
        except Exception:
            return [0]

    def _mem_pct_recent():
        try:
            mi = {}
            for l in open("/proc/meminfo"):
                if l.startswith("MemTotal") or l.startswith("MemAvailable"):
                    p = l.split(); mi[p[0].rstrip(":")] = int(p[1]) * 1024
            tot = mi.get("MemTotal", 0)
            return [round(100 * (1 - mi.get("MemAvailable", 0) / max(1, tot)), 1)]
        except Exception:
            return [0]

    @app.post("/api/mon/export")   # 导出监控数据为 CSV 文本返回
    def api_mon_export():
        d = {"cpu": _cpu_pct_recent(), "mem": _mem_pct_recent()}
        csv = "ts,cpu%,mem%\n" + "\n".join(f"{i},{v1},{v2}" for i, (v1, v2) in enumerate(zip(d["cpu"], d["mem"])))
        return jsonify({"ok": True, "csv": csv, "rows": [{"ts": i, "cpu": v1, "mem": v2} for i, (v1, v2) in enumerate(zip(d["cpu"], d["mem"]))]})

