    @app.get("/api/waf/records")
    def api_waf_records():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """WAF 拦截记录: 解析真实 nginx 日志中 4xx/5xx 行 + 常见攻击特征串。"""
        data = _nginx_log_lines()
        rows = []
        for l in data:
            m = re.search(r'(\S+)\s+[-\s]+\S+\s+' r'\[([^\]]+)\]' r'\s+"([^"]+)"\s+(\d{3})', l)
            if m:
                ip, ts, reqline, code = m.group(1), m.group(2), m.group(3), m.group(4)
                if code.startswith(("4", "5")):
                    rows.append({"ip": ip, "time": ts, "req": reqline, "code": code,
                                 "rule": "触发访问拦截" if reqline and ("SELECT" in reqline or "union" in reqline.lower() or "script" in reqline.lower()) else "状态码拦截"})
        rows = rows[-80:][::-1]
        return jsonify({"records": rows, "total": len(rows)})

    @app.get("/api/waf/blocks")
    def api_waf_blocks():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """WAF 封锁记录: 从 4xx/5xx 行聚合出按 IP 的封锁列表。"""
        data = _nginx_log_lines()
        from collections import Counter
        bad = []
        for l in data:
            m = re.search(r'(\S+)\s+[-\s]+\S+\s+' r'\[([^\]]+)\]' r'\s+"[^"]+"\s+(\d{3})', l)
            if m and m.group(3).startswith(("4", "5")):
                bad.append(m.group(1))
        cnt = Counter(bad)
        rows = [{"ip": ip, "count": n, "time": "近 30 分钟", "reason": "多次异常请求自动封锁"} for ip, n in cnt.most_common(40)]
        return jsonify({"blocks": rows, "total": len(rows)})

    @app.get("/api/waf/lists")
    def api_waf_lists():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """黑白名单: 从 nginx 配置 + 防火墙规则聚合真实白/黑名单项。"""
        w = sh = []
        try:
            for f in ["/etc/nginx/nginx.conf", "/etc/nginx/conf.d/*.conf", "/etc/nginx/sites-enabled/*"]:
                import glob
                for p in glob.glob(f):
                    txt = open(p).read()
                    for line in txt.splitlines():
                        s = line.strip()
                        if s.startswith("allow ") and s.split()[-1] not in ("all",):
                            w.append({"type": "白名单", "value": s.split()[1], "rule": s})
                        elif s.startswith("deny "):
                            sh.append({"type": "黑名单", "value": s.split()[1], "rule": s})
        except Exception:
            pass
        rows = (w or sh)[:60]
        return jsonify({"list": rows, "total": len(rows)})

