    @app.get("/api/kvm")
    def api_kvm():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """KVM 虚拟机管理真实探测: 硬件虚拟化 / libvirt 连接 / 在线虚拟机与存储池计数。
        无 KVM 能力时返回 error, 前端以真实空态呈现。"""
        try:
            cpu = open("/proc/cpuinfo").read().lower()
            hw = ("vmx" in cpu) or ("svm" in cpu)
            dev = os.path.exists("/dev/kvm")
            virsh = _sp.run(["bash", "-lc", "command -v virsh >/dev/null 2>&1 && echo yes || echo no"],
                            capture_output=True, text=True, timeout=5).stdout.strip() == "yes"
            vms = pools = running = stopped = creating = 0
            lib_ok = False; lib_err = ""
            if virsh:
                conn = _sp.run(["timeout", "6", "virsh", "-c", "qemu:///system", "list", "--all"],
                               capture_output=True, text=True, timeout=10)
                if conn.returncode == 0:
                    lib_ok = True
                    for ln in conn.stdout.splitlines():
                        p = ln.split()
                        if len(p) >= 2 and p[0].isdigit():
                            vms += 1
                            st = " ".join(p[2:]) if len(p) > 2 else p[1]
                            if "running" in st: running += 1
                            elif "shut" in st or "in shutdown" in st or "off" in st: stopped += 1
                            elif "create" in st or "在创建" in st: creating += 1
                    pl = _sp.run(["timeout", "6", "virsh", "-c", "qemu:///system", "pool-list"],
                                 capture_output=True, text=True, timeout=10)
                    if pl.returncode == 0:
                        pools = sum(1 for ln in pl.stdout.splitlines() if ln.strip() and not ln.strip().startswith("---") and not ln.strip().startswith("Name"))
                else:
                    lib_err = (conn.stderr or conn.stdout).strip().splitlines()[:2]
            if not (hw and dev and lib_ok):
                return jsonify({"ok": False, "error": "no kvm", "hw": hw, "dev": dev, "virsh": virsh,
                                "lib_ok": lib_ok, "msg": (lib_err[0] if lib_err else "未检测到可用的 KVM 硬件虚拟化能力")})
            return jsonify({"ok": True, "vms": vms, "pools": pools, "running": running,
                            "stopped": stopped, "creating": creating})
        except Exception as e:
            return jsonify({"ok": False, "error": "no kvm", "msg": str(e)})

