    @app.get("/api/overview")
    def api_overview():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """总览首页实时数据: 快速跳转计数 + 状态 + 系统信息 + 应用 + 主机TOP表(多机)。"""
        now = time.time()
        gb = 1024.0 ** 3
        def _mem_hum(b):
            return f"{b/gb:.2f} GB" if b >= gb else f"{b/(1024**2):.2f} MB"
        # ---- 系统信息 ----
        hostname = socket.gethostname()
        try: dist = (open("/etc/os-release").read().split('PRETTY_NAME="')[1].split('"')[0])
        except Exception: dist = ""
        kver = platform_machine_kernel()
        arch = platform_machine_kernel(True)
        mem = {}
        try:
            lines = [l for l in open("/proc/meminfo").read().splitlines() if ':' in l]
            def val(k):
                for l in lines:
                    if l.startswith(k):
                        return int(l.split()[1]) * 1024
                return 0
            total = val("MemTotal"); avail = val("MemAvailable"); used = total - avail
            mem = {"total": total, "used": used, "avail": avail, "free": val("MemFree"),
                   "share": val("Shmem"), "buff": val("Buffers") + val("Cached"),
                   "pct": round(used * 100.0 / total, 2) if total else 0}
        except Exception: pass
        # ---- CPU 负载 ----
        load = [float(x) for x in open("/proc/loadavg").read().split()[:3]]
        cores = os.cpu_count() or 1
        cpu_model = ""; phys_cores = cores; cpu_mhz = 0
        try:
            cpuinfo = open("/proc/cpuinfo").read()
            if "model name" in cpuinfo:
                blk = cpuinfo.split("model name")
                for part in blk[1:]:
                    cpu_model = part.split(":")[1].strip().split("\n")[0]
                    break
            phys = set()
            mhz = []
            for blk in cpuinfo.split("\n\n"):
                pid = None
                for ln in blk.splitlines():
                    if ln.startswith("physical id"): pid = ln.split(":", 1)[1].strip()
                    elif ln.startswith("cpu MHz"): mhz.append(float(ln.split(":", 1)[1].strip()))
                if pid is not None: phys.add(pid)
            if phys: phys_cores = len(phys)
            if mhz: cpu_mhz = round(sum(mhz) / len(mhz))
        except Exception: pass
        # 每个逻辑 CPU 瞬时使用率(/proc/stat 两次采样差量)
        def _cpu_usage():
            try:
                def snap():
                    d = {}
                    for ln in open("/proc/stat").read().splitlines():
                        if not ln.startswith("cpu"): continue
                        p = ln.split()
                        if not p[0][3:].isdigit() and p[0] != "cpu": continue
                        vals = [int(x) for x in p[1:]]
                        idle = vals[3] + (vals[4] if len(vals) > 4 else 0)
                        d[p[0]] = {"i": idle, "t": sum(vals)}
                    return d
                a = snap(); time.sleep(0.2); b = snap()
                out = []
                for k in sorted([k for k in a if k != "cpu"],
                                key=lambda k: (int(k[3:]), ) if k[3:].isdigit() else (0,)):
                    di = b[k]["i"] - a[k]["i"]; dt = b[k]["t"] - a[k]["t"]
                    out.append(round(100.0 * (1 - di / max(1, dt)), 2))
                return out
            except Exception: return []
        cpu_usage = _cpu_usage()
        # ---- 磁盘 ----
        disk = {}
        try:
            st = os.statvfs("/")
            total = st.f_blocks * st.f_frsize
            free = st.f_bavail * st.f_frsize
            used = (st.f_blocks - st.f_bfree) * st.f_frsize
            disk = {"total": total, "used": used, "free": free, "pct": round(used*100.0/total,2) if total else 0,
                    "mount": "/", "dev": "", "fstype": "ext4",
                    "inode": {"total": st.f_files, "used": st.f_files - st.f_ffree, "free": st.f_ffree,
                              "pct": round((st.f_files - st.f_ffree) * 100.0 / st.f_files, 2) if st.f_files else 0}}
            try:
                import shutil
                du = shutil.disk_usage("/")
                disk["used"] = du.used; disk["free"] = du.free
            except Exception: pass
            try:
                for ln in open("/proc/mounts").read().splitlines():
                    if ln.split()[-2] == "/" and ln.split()[0].startswith("/dev"):
                        disk["dev"] = ln.split()[0]; disk["fstype"] = ln.split()[2]; break
            except Exception: pass
        except Exception: pass
        # ---- 启动/运行时间 ----
        boot = None
        try:
            st = os.stat("/proc")
            boot = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(st.st_mtime))
        except Exception: pass
        up = float(open("/proc/uptime").read().split()[0]) if os.path.exists("/proc/uptime") else 0
        d, r = divmod(int(up), 86400); h, r = divmod(r, 3600); m, s = divmod(r, 60)
        uptime = f"{d}天 {h}小时 {m}分钟 {s}秒"
        # ---- 快速跳转计数 ----
        sites = 0
        try: sites = len(os.listdir(SITES_DIR))
        except Exception: pass
        c = db()
        dbcnt = c.execute("SELECT COUNT(*) FROM hosts").fetchone()[0]
        dbassets = len(_load_dbassets())
        compose_cnt = 0
        try: compose_cnt = len(os.listdir(COMPOSE_DIR))
        except Exception: pass
        docker_cnt = docker_containers().get("containers", [])
        running = sum(1 for x in docker_cnt if x["state"] == "running")
        # ---- 网卡列表 ----
        nics = [n for n in os.listdir("/sys/class/net") if not n.startswith(("veth", "br-"))]
        # ---- 应用(compose 栈) ----
        apps = []
        try:
            for name in sorted(os.listdir(COMPOSE_DIR)):
                f = os.path.join(COMPOSE_DIR, name, "docker-compose.yml")
                if os.path.exists(f):
                    apps.append({"name": name, "tech": "compose", "services": running})
        except Exception: pass
        # ---- 多机主机TOP ----
        hosts = [{"name": r[0], "ip": r[1], "load1": r[2], "mem": r[3], "disk": r[4],
                  "docker": r[5], "sev": r[6]} for r in c.execute(
            "SELECT name,ip,loaded,mem,disk,docker,sev FROM hosts ORDER BY sev DESC, name")]
        return jsonify({"ok": True,
            "hostname": hostname, "dist": dist, "kernel": kver, "arch": arch,
            "ip": request.host.split(":")[0],
            "boot": boot, "uptime": uptime, "load": load, "cores": cores, "cpu_model": cpu_model,
            "phys_cores": phys_cores, "cpu_mhz": cpu_mhz, "cpu_usage": cpu_usage,
            "mem": mem, "disk": disk,
            "quicks": {"agent": dbcnt, "site": sites, "db": dbassets, "app": compose_cnt, "running": running},
            "apps": apps, "nics": nics, "hosts": hosts})

    @app.get("/api/net")
    def api_net():
        up = dn = 0
        chunks = {}
        try:
            for line in open("/proc/net/dev").read().splitlines()[2:]:
                p = line.split(":")
                if len(p) < 2: continue
                name = p[0].strip()
                if name.startswith(("veth", "br-")): continue
                f = p[1].split()
                rx = int(f[0]); tx = int(f[8])
                up += tx; dn += rx
                chunks[name] = {"up": tx, "dn": rx}
        except Exception: pass
        return jsonify({"total": {"up": up, "dn": dn,
            "sendTxt": fmt_bytes(up), "recvTxt": fmt_bytes(dn)}, "nics": chunks})

