    # ---- 容器 > 更多 > 目录: 容器内文件浏览(对标 1Panel file 页) ----
    @app.get("/api/docker/<cid>/files")
    def api_docker_files(cid):
        path = (request.args.get("path") or "/").strip() or "/"
        if not path.startswith("/"): path = "/" + path
        if ".." in path.split("/"): return jsonify({"ok": False, "error": "bad path", "files": []}), 400
        ok, out = _docker(["exec", cid, "sh", "-c", "ls -lA " + _shq(path)], timeout=40)
        if not ok:
            return jsonify({"ok": False, "error": out, "path": path, "files": []})
        rows = []
        for line in out.splitlines():
            if line.startswith("total ") or not line.strip(): continue
            p = line.split(None, 8)
            if len(p) < 9: continue
            mode, size, name = p[0], p[4], p[8]
            if name in (".", ".."): continue
            if mode.startswith("l") and " -> " in name: name = name.split(" -> ")[0]
            is_dir = mode.startswith("d")
            rows.append({"name": name, "is_dir": is_dir,
                         "size": int(size) if size.isdigit() else 0, "mode": mode})
        rows.sort(key=lambda x: (not x["is_dir"], x["name"]))
        return jsonify({"ok": True, "path": path, "files": rows})

    @app.get("/api/docker/<cid>/file")
    def api_docker_file(cid):
        path = (request.args.get("path") or "").strip()
        if not path.startswith("/") or ".." in path.split("/"):
            return jsonify({"ok": False, "error": "bad path"}), 400
        try:
            r = _sp.run(["docker", "exec", cid, "cat", path], capture_output=True, timeout=120)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500
        if r.returncode != 0:
            return jsonify({"ok": False, "error": r.stderr.decode("utf-8", "ignore")}), 404
        fn = os.path.basename(path)
        return Response(r.stdout, mimetype="application/octet-stream",
                        headers={"Content-Disposition": "attachment; filename*=UTF-8''" + urllib.parse.quote(fn)})

