    @app.post("/api/docker/<cid>/rmfile")
    def api_docker_rmfile(cid):
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        paths = d.get("paths") or []
        if not paths: return jsonify({"ok": False, "error": "empty"}), 400
        for p in paths:
            if not str(p).startswith("/") or ".." in str(p).split("/"):
                return jsonify({"ok": False, "error": "bad path"}), 400
        ok, out = _docker(["exec", cid, "rm", "-rf", "--"] + paths, timeout=120)
        return jsonify({"ok": ok, "error": "" if ok else out})

    @app.post("/api/docker/<cid>/upload")
    def api_docker_upload(cid):
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        f = request.files.get("file")
        path = (request.form.get("path") or "/").strip() or "/"
        if not f or not path.startswith("/") or ".." in path.split("/"):
            return jsonify({"ok": False, "error": "bad request"}), 400
        buf = io.BytesIO()
        with tarfile.open(fileobj=buf, mode="w") as tf:
            ti = tarfile.TarInfo(f.filename or "upload.bin")
            data = f.read()
            ti.size = len(data)
            ti.mtime = int(time.time())
            tf.addfile(ti, io.BytesIO(data))
        buf.seek(0)
        try:
            r = _sp.run(["docker", "cp", "-", "%s:%s" % (cid, path)],
                        input=buf.getvalue(), capture_output=True, timeout=300)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500
        ok = r.returncode == 0
        return jsonify({"ok": ok, "error": "" if ok else r.stderr.decode("utf-8", "ignore")})

