    # ---- SSL & 证书 (F) ----
    ACMESH = os.path.expanduser("~/.acme.sh/acme.sh")
    os.makedirs(CERTS_DIR, exist_ok=True)

    def _load_certlist():
        out = []
        for nm in os.listdir(ACME_HOME := os.path.expanduser("~/.acme.sh")):
            if not nm.endswith("_ecc"): continue
            d = os.path.join(os.path.expanduser("~/.acme.sh"), nm)
            cf = os.path.join(d, nm[:-4] + ".conf")
            if not os.path.exists(cf): continue
            dom = nm[:-4]
            rec = {"domain": dom}
            try:
                t = open(cf).read()
                rec["alt"] = re.search(r"Le_Alt='([^']*)'", t) and re.search(r"Le_Alt='([^']*)'", t).group(1)
                rec["webroot"] = re.search(r"Le_Webroot='([^']*)'", t) and re.search(r"Le_Webroot='([^']*)'", t).group(1)
            except Exception: pass
            cer = os.path.join(d, dom + ".cer")
            if os.path.exists(cer):
                try:
                    o = _sp.run(["openssl","x509","-in",cer,"-noout","-dates","-enddate","-subject"],capture_output=True,text=True)
                    rec["info"] = o.stdout.strip()
                    m = re.search(r"notAfter=(.*)", o.stdout)
                    rec["expires"] = m.group(1) if m else "?"
                    ren = re.search(r"Le_NextRenewTime='?(\d+)'?", open(cf).read())
                    if ren:
                        import datetime as _dt
                        rec["renew"] = _dt.datetime.fromtimestamp(int(ren.group(1))).strftime("%Y-%m-%d")
                except Exception: rec["expires"]="?"
            out.append(rec)
        return out

    def _cert_issue(domain, alt=""):
        if not os.path.exists(ACMESH):
            return {"ok": False, "error": f"acme.sh 不存在: {ACMESH}"}
        args = [ACMESH, "--issue", "--dns", "dns_cf", "-d", domain]
        for a in alt.split(","):
            a = a.strip()
            if a: args += ["-d", a]
        args += ["--keylength", "ec-256", "--server", "letsencrypt"]
        env = dict(os.environ, HOME=os.path.expanduser("~"), CF_Token_Confirm="1")
        try:
            r = _sp.run(args, capture_output=True, text=True, timeout=300, env=env)
            cer = os.path.expanduser(f"~/.acme.sh/{domain}_ecc/{domain}.cer")
            star = os.path.exists(cer)
            # 非 0 退出也可能是"已存在且未到期, 跳过续期"(acme.sh exit 2), 此时证书仍可用, 不算失败
            has_valid = False
            if star:
                try:
                    out = _sp.run(["openssl","x509","-in",cer,"-dates","-noout"],
                                  capture_output=True, text=True, timeout=15).stdout
                    import time as _t
                    end = _t.strptime(out.split("notAfter=")[-1].split("\n")[0], "%b %d %H:%M:%S %Y %Z")
                    has_valid = _t.mktime(end) > _t.time()
                except Exception:
                    has_valid = True
            ok = (r.returncode == 0 or has_valid) and star
            msg = ("证书已签发/已就绪" if ok else "签发失败") + "\n" + (r.stdout + r.stderr)[-800:]
            if ok: log_event("cert", "ok", f"issue {domain} alt={alt or 'None'}")
            else: log_event("cert", "err", f"issue {domain}: {msg[:120]}")
            return {"ok": ok, "msg": msg}
        except Exception as e:
            log_event("cert", "err", f"issue {domain}: {e}")
            return {"ok": False, "error": str(e)}

    # 面板原生自动续签: 后台线程周期扫描, 到 ARI 续期窗就调 _cert_issue 续
    RENEW_CHECK_EVERY = 6*3600   # 每 6h 扫一次
    def _cert_due():
        """返回已到期/临近续期窗的域名列表 (读 acme.sh conf 的 Le_NextRenewTime/notAfter)"""
        due, now = [], int(time.time())
        for c in _load_certlist():
            dom = c.get("domain")
            src = os.path.expanduser(f"~/.acme.sh/{dom}_ecc")
            if not os.path.isdir(src): continue
            nr = None
            try:
                t = open(os.path.join(src, dom + ".conf")).read()
                nr = re.search(r"Le_NextRenewTime='?(\d+)'?", t)
                nr = int(nr.group(1)) if nr else None
            except Exception: nr = None
            if nr is not None and nr <= now: due.append(dom); continue
            # 无 Le_NextRenewTime 时回退: notAfter 距今 < 30 天视为需要续
            try:
                o = _sp.run(["openssl","x509","-in",os.path.join(src,dom+".cer"),
                             "-noout","-enddate"], capture_output=True, text=True, timeout=15).stdout
                m = re.search(r"notAfter=(.*)", o)
                if m:
                    import datetime as _dt
                    end = _dt.datetime.strptime(m.group(1).strip(), "%b %d %H:%M:%S %Y %Z").timestamp()
                    if end - now < 30*86400: due.append(dom)
            except Exception: pass
        return due

    def _cert_autorenew_worker():
        import threading as _th
        def loop():
            while True:
                try:
                    for dom in _cert_due():
                        r = _cert_issue(dom)
                        log_event("cert", "ok" if r.get("ok") else "err",
                                  f"auto-renew {dom}: {'ok' if r.get('ok') else r.get('msg','')[:60]}")
                except Exception as e:
                    log_event("cert", "err", f"auto-renew scan: {e}")
                time.sleep(RENEW_CHECK_EVERY)
        _th.Thread(target=loop, daemon=True).start()

    def _cert_deploy(domain):
        """把证书拷到 CERTS_DIR, 供站点/网关挂载。"""
        src = os.path.expanduser(f"~/.acme.sh/{domain}_ecc")
        if not os.path.isdir(src): return {"ok": False, "error": "no cert dir"}
        dst = os.path.join(CERTS_DIR, domain)
        os.makedirs(dst, exist_ok=True)
        for f in ("fullchain.cer", domain + ".cer", domain + ".key", "ca.cer"):
            if os.path.exists(os.path.join(src, f)):
                _sp.run(["cp", os.path.join(src, f), os.path.join(dst, f)])
        log_event("cert", "info", f"deployed {domain} -> {dst}")
        return {"ok": True, "dir": dst}

