    @app.post("/api/audit/clean")
    def api_audit_clean():
        """清空日志：{logType:'operation'|'login'}（同 1Panel /core/logs/clean）"""
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        _ensure_log_tables()
        lt = (request.get_json(force=True, silent=True) or {}).get("logType") or "operation"
        if lt in ("system", "task"):
            p = os.path.join(DATA, "joblog.json" if lt == "task" else "syslog_cleared.json")
            if lt == "task":
                try: open(p, "w").write("[]")
                except Exception: pass
            else:
                try: open(p, "w").write(time.strftime("%Y-%m-%d %H:%M:%S"))
                except Exception: pass
            try: _op_log("logs", "clear", status="Success", detail_zh="清空日志", detail_en="Clear logs")
            except Exception: pass
            return jsonify({"ok": True})
        c = db()
        c.execute("DELETE FROM login_logs" if lt == "login" else "DELETE FROM operation_logs"); c.commit()
        try: _op_log("logs", "clear", status="Success", detail_zh="清空日志", detail_en="Clear logs")
        except Exception: pass
        return jsonify({"ok": True})

