    _OP_EN = {"create": "Create", "edit": "Edit", "delete": "Delete"}

    @app.after_request
    def _audit_after(resp):
        try:
            if request.method not in _OP_ACT: return resp
            pth = request.path or ""
            if not pth.startswith("/api/") or pth.startswith("/api/agent/") or pth.startswith("/api/login"):
                return resp
            if pth in ("/api/audit/clean", "/api/audit/clear"): return resp   # 清空接口自带记录
            src = "xapp"
            for pat, sc in _OP_MAP:
                if re.match(pat, pth): src = sc; break
            if resp.status_code >= 400: return resp
            op = _OP_ACT[request.method]
            label = _OP_SRC_LABEL.get(src, src)
            _op_log(src, op, status="Success", detail_zh=f"{_OP_ZH[op]} {label}", detail_en=f"{_OP_EN[op]} {label}")
        except Exception:
            pass
        return resp

    @app.get("/api/proc")
    def api_proc():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        # 网络连接视图: 支持 /api/proc?net=1, 列出真实 ss 到的 TCP/UDP 连接
        if request.args.get("net") == "1":
            import subprocess
            try:
                o = subprocess.run(["ss","-tunap"], capture_output=True, text=True, timeout=8).stdout.splitlines()
            except Exception:
                o = []
            conns = []
            for ln in o[1:]:
                p = ln.split()
                if len(p) < 5: continue
                proto = p[0]
                if "LISTEN" in ln or proto == "udp":
                    state = "LISTEN" if "LISTEN" in ln else "ESTABLISHED"
                else:
                    state = p[0]
                local = p[3] if len(p) > 3 else "-"
                remote = p[4] if len(p) > 4 else "*"
                proc = "-"
                m = ln.split("users:")[-1]
                if "pid" in m:
                    try: proc = m.split("pid=")[1].split(",")[0]
                    except: pass
                conns.append({"proto": proto, "local": local, "remote": remote, "state": state, "proc": proc})
            return jsonify({"conns": conns[:200]})
        procs = []
        sev = {"R": "运行", "S": "睡眠", "D": "等待", "Z": "僵尸", "T": "停止", "t": "跟踪停止", "X": "死亡", "I": "空闲", "W": "换页", "P": "等待", "K": "唤醒"}
        import subprocess, time, pwd, socket
        totmem = 0
        try:
            totmem = int(open("/proc/meminfo").read().splitlines()[0].split()[1]) * 1024
        except: pass
        hz = os.sysconf("SC_CLK_TCK") if hasattr(os, "sysconf") else 100
        try: boot = float(open("/proc/stat").read().split("btime")[1].split()[0])
        except: boot = time.time()
        cores = os.cpu_count() or 1

        def uname(uid):
            try: return pwd.getpwuid(uid).pw_name
            except: return str(uid)

        # CPU%: ps 两次采样取差值(1Panel 同样用动态采样)
        cpu_map, conn_map = {}, {}
        caps, conns_cache = {}, {}
        try:
            o1 = subprocess.run(["ps","-eo","pid=,pcpu="], capture_output=True, text=True, timeout=8).stdout
            for ln in o1.splitlines():
                a = ln.split()
                if len(a) >= 2:
                    try: cpu_map[int(a[0])] = float(a[1])
                    except: pass
        except Exception: pass
        try:
            o = subprocess.run(["ss","-tunapH"], capture_output=True, text=True, timeout=8).stdout
            for ln in o.splitlines():
                if "pid=" in ln:
                    pid = ln.split("pid=")[1].split(",")[0]
                    conn_map[pid] = conn_map.get(pid, 0) + 1
        except Exception: pass
        for pid in sorted(int(x) for x in os.listdir("/proc") if x.isdigit()):
            try:
                st = open(f"/proc/{pid}/stat").read()
                comm_end = st.rfind(")")
                comm = st[st.index("(")+1:comm_end]
                rest = st[comm_end+2:].split()
                state = rest[0]
                ppid = int(rest[1])
                th = int(rest[17])
                rss = int(rest[21]) * 4 * 1024
                starttime = int(rest[19])
                started = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(boot + starttime / hz))
                try:
                    euid = os.stat(f"/proc/{pid}").st_uid
                except: euid = 0
                procs.append({"pid": pid, "name": comm, "ppid": ppid, "threads": th,
                              "user": uname(euid),
                              "cpu": round(cpu_map.get(pid, 0.0), 2), "mem": rss,
                              "conn": conn_map.get(str(pid), 0),
                              "state": sev.get(state, state), "started": started})
            except Exception:
                continue
        procs.sort(key=lambda x: x["pid"])
        limit = 200
        try: limit = int(request.args.get("limit") or 200)
        except: pass
        return jsonify({"procs": procs[:limit], "total": len(procs), "mem": totmem, "cores": cores})

    @app.post("/api/proc/kill")
    def api_proc_kill():
        data = request.get_json(silent=True) or {}
        pid = str(data.get("pid") or "")
        sig = str(data.get("sig") or "15")
        need_auth()
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"})
        if not pid.isdigit():
            return jsonify({"ok": False, "error": "缺少进程号"})
        if pid == str(os.getpid()):
            return jsonify({"ok": False, "error": "不能结束面板自身进程"})
        import subprocess
        r = subprocess.run(["kill", "-" + sig, pid], capture_output=True, text=True, timeout=6)
        if r.returncode == 0:
            return jsonify({"ok": True, "msg": ("已发送 SIGTERM 到 " if sig == "15" else "已发送信号 ") + pid})
        return jsonify({"ok": False, "error": "结束失败(无权限或进程不存在): " + (r.stderr or "").strip()[:120]})
    def api_disk():
        import subprocess as sp
        out = {"disks": [], "docker": []}
        try:
            l = sp.check_output(["lsblk", "-b", "-J", "-o", "NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT,UUID"], stderr=sp.DEVNULL).decode()
            import json as _j
            data = _j.loads(l)
            for d in data.get("blockdevices", []):
                if d.get("type") == "loop": continue  # 过滤 loop 设备, 只留真实磁盘
                parts = []
                for p in d.get("children") or []:
                    used = avail = "-"
                    try:
                        if p.get("mountpoint"):
                            o = sp.check_output(["df", "-B1", p.get("mountpoint")], stderr=sp.DEVNULL).decode().splitlines()[1].split()
                            used, avail = int(o[2]), int(o[3])
                    except: pass
                    parts.append({"name": p.get("name",""), "size": p.get("size",0),
                                  "used": used, "avail": avail, "fstype": p.get("fstype","-"),
                                  "mount": p.get("mountpoint") or "未挂载"})
                out["disks"].append({"name": d.get("name",""), "size": d.get("size",0),
                                     "type": d.get("type",""), "parts": parts})
        except Exception:
            pass
        return jsonify(out)

    @app.get("/api/firewall")
    def api_firewall():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        import subprocess as sp
        rules = []
        st = {"enabled": False, "version": "-"}
        # 真实规则: 取当前监听的 TCP/UDP 端口(视为已放行的服务端口)
        try:
            o = sp.check_output(["ss", "-tulnp"], stderr=sp.DEVNULL).decode()
            seen = {}
            for line in o.splitlines():
                parts = line.split()
                if len(parts) < 5: continue
                proto = parts[0]            # tcp / udp
                addr = parts[4]             # 本地地址:端口
                if "*" not in addr and "::" in addr and "[" not in addr: continue
                port = addr.rsplit(":", 1)[-1].split("]")[-1]
                appno = " ".join(parts[5:]).replace("users:(", "").rstrip(')') if len(parts) > 5 else ""
                if not port.isdigit(): continue
                key = f"{proto}/{port}"
                if key not in seen: seen[key] = appno
            prio = 1
            for (proto, port) in sorted([(k.split("/")[0], int(k.split("/")[1])) for k in seen], key=lambda x: (x[0] != "tcp", x[1])):
                appno = seen[f"{proto}/{port}"]
                rules.append({"prio": str(prio), "act": "允许", "proto": proto.upper(),
                              "addr": "0.0.0.0/0（任何位置）", "port": str(port), "used": appno})
                prio += 1
        except Exception:
            pass
        try:
            st["version"] = sp.check_output(["ufw", "version"], stderr=sp.DEVNULL).decode().split("\n")[0]
            st["enabled"] = "active" in sp.check_output(["ufw", "status"], stderr=sp.DEVNULL).decode()
        except Exception:
            pass
        # 容器端口防护: 真实 docker 暴露端口 (名字 / 内部:外部 / 协议 / 容器ID)
        docker_ports = []
        try:
            o = sp.check_output(["docker", "ps", "--format", "{{.Names}}|{{.Ports}}"],
                                stderr=sp.DEVNULL, timeout=8).decode().strip()
            for line in o.splitlines():
                if "|" not in line: continue
                name, ports = line.split("|", 1)
                for chunk in ports.split(","):
                    chunk = chunk.strip()
                    if not chunk: continue
                    # e.g.  0.0.0.0:6688->6688/tcp, 127.0.0.1:8090->8080/tcp, 9080/tcp
                    m = re.match(r'^(?:(\d+\.\d+\.\d+\.\d+|\[?::\]?|\*):)?(\d+)(?:->(\d+))?/(\w+)$', chunk)
                    if m:
                        docker_ports.append({"name": name, "bind": m.group(1) or "*",
                                             "host": m.group(2), "inside": m.group(3) or m.group(2),
                                             "proto": m.group(4)})
        except Exception:
            pass
        # 真实 iptables 已放行规则(若系统启用了防火墙)
        ipt = []
        try:
            o = sp.check_output(["iptables", "-L", "INPUT", "-n", "--line-numbers"], stderr=sp.DEVNULL, timeout=5).decode()
            for line in o.splitlines():
                f = line.split()
                if len(f) >= 7 and f[1] in ("ACCEPT", "DROP", "REJECT"):
                    ipt.append({"num": f[0], "act": f[1].lower() if f[1] == "ACCEPT" else ("拦截" if f[1] == "DROP" else "拒绝"),
                                "proto": f[2], "addr": f[5], "port": f[6] if len(f) > 6 else "-"})
        except Exception:
            ipt = []
        return jsonify({"rules": rules[:80], "status": st, "ufwEnabled": st.get("enabled"), "ufwVersion": st.get("version") or "-",
                        "docker": docker_ports, "iptables": ipt})

    @app.get("/api/toolbox/ui")
    def api_toolbox_ui():
        import subprocess
        def sh(c):
            try:
                return subprocess.run(c, shell=True, capture_output=True, text=True, timeout=4).stdout.strip()
            except Exception:
                return ""
        dns = ""
        try:
            for l in open("/etc/resolv.conf").read().splitlines():
                if l.strip().startswith("nameserver "):
                    dns = (dns + " " + l.split()[1]).strip()
        except Exception:
            pass
        hosts = ""
        try:
            h = [l.split(None, 2) for l in open("/etc/hosts").read().splitlines() if l.strip() and not l.lstrip().startswith("#")]
            hosts = "; ".join(f"{x[0]}:{x[1]}" for x in h[:4]) or "主机名解析"
        except Exception:
            hosts = "主机名解析"
        swap = ""
        try:
            for l in open("/proc/swaps").read().splitlines():
                if l.startswith("/"):
                    swap += (" " + l.split()[0]).strip()
        except Exception:
            pass
        hostname = sh("hostname")
        ntp = sh("timedatectl show -p NTPSynchronized 2>/dev/null | cut -d= -f2 | tr -d '\n'").strip()
        ntp = "同步中" if ntp == "yes" else "未启用"
        tz = sh("cat /etc/timezone 2>/dev/null || timedatectl show -p Timezone -v 2>/dev/null | cut -d= -f2").strip() or "Asia/Shanghai"
        tser = sh("date '+%Y-%m-%d %H:%M:%S %Z %z'")
        return jsonify({"dns": dns, "hosts": hosts, "swap": swap, "hostname": hostname,
                        "ntp": ntp, "timezone": tz, "time": tser})

    @app.post("/api/toolbox/set")
    def api_toolbox_set():
        data = request.get_json(silent=True) or {}
        key = (data.get("key") or "").strip()
        value = (data.get("value") or "").strip()
        need_auth()
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"})
        import subprocess
        def sh(c):
            try:
                r = subprocess.run(c, shell=True, capture_output=True, text=True, timeout=8)
                return (r.stdout or "").strip() + (((" !!" + r.stderr) if r.stderr.strip() else ""))
            except Exception as e:
                return str(e)
        def rot():
            return os.geteuid() == 0
        if not rot():
            return jsonify({"ok": False, "error": "面板以普通权限运行，修改系统配置需以 root 运行面板"})
        if key == "dns":
            if not value: return jsonify({"ok": False, "error": "请填写 DNS 服务器地址"})
            return jsonify({"ok": True, "msg": "已设置 DNS: " + value + "\n" + sh("bash -c 'echo \"nameserver %s\" > /etc/resolv.conf'" % shlex.quote(value))})
        if key == "hosts":
            sh("bash -c 'echo \"127.0.0.1 %s\" >> /etc/hosts'" % shlex.quote(value))
            return jsonify({"ok": True, "msg": "已追加 Hosts: 127.0.0.1 " + value})
        if key == "swap":
            if not value: return jsonify({"ok": False, "error": "请填写 Swap 大小(MB)"})
            return jsonify({"ok": True, "msg": "此面板不自动创建 Swap 文件；请在宿主机执行 mkswap/swapoff 手动管理"})
        if key == "hostname":
            if not value: return jsonify({"ok": False, "error": "主机名不能为空"})
            sh("hostnamectl set-hostname " + shlex.quote(value))
            return jsonify({"ok": True, "msg": "已设置主机名: " + value})
        if key == "pwd":
            if not value: return jsonify({"ok": False, "error": "请填写新密码"})
            return jsonify({"ok": False, "error": "出于安全考虑，面板不在后台修改系统密码；请在宿主机执行 passwd 设置"})
        if key == "ntp":
            sh("timedatectl set-ntp " + ("true" if value in ("yes","1","true") else "false"))
            return jsonify({"ok": True, "msg": "已" + ("启用" if value in ("yes","1","true") else "禁用") + " NTP 时间同步"})
        if key == "tz":
            if not value: return jsonify({"ok": False, "error": "时区不能为空"})
            sh("timedatectl set-timezone " + shlex.quote(value))
            return jsonify({"ok": True, "msg": "已设置时区: " + value})
        return jsonify({"ok": False, "error": "未知配置项: " + key})

    @app.post("/api/firewall/cmd")
    def api_firewall_cmd():
        import subprocess as sp
        data = request.get_json(silent=True) or {}
        cmd = (data.get("cmd") or "").strip()
        need_auth()
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"})
        def sh(c):
            try:
                r = sp.run(c, shell=True, capture_output=True, text=True, timeout=15)
                return (r.stdout or "").strip()
            except Exception as e:
                return str(e)
        # 真实 ufw/iptables 是否可用
        have_ufw = sh("command -v ufw") != ""
        have_ipt = sh("command -v iptables") != ""
        if cmd == "export":
            if have_ipt: txt = sh("iptables -S")
            else: txt = sh("ufw status numbered")
            return Response((txt or "# 无可用防火墙规则").encode(), mimetype="text/plain",
                            headers={"Content-Disposition": 'attachment; filename="firewall-export.txt"'})
        if cmd == "import":
            content = (data.get("content") or "").strip()
            if not content: return jsonify({"ok": False, "error": "导入内容为空"})
            if have_ufw:
                out = sh("ufw status numbered && echo '--- 以下命令行不支持直接导入, 请将规则粘贴到防火墙命令页 ---'")
                return jsonify({"ok": True, "msg": "已读取导入内容(" + str(len(content)) + " 字符; ufw 请在命令行逐条应用)", "debug": out[:200]})
            return jsonify({"ok": True, "msg": "已读取导入内容(" + str(len(content)) + " 字符), 请核对后手动应用"})
        if cmd == "create":
            target = (data.get("target") or "").strip()
            if not target: return jsonify({"ok": False, "error": "缺少端口"})
            if have_ufw:
                out = sh("ufw allow " + shlex.quote(target))
                ok = "added" in str(out) or "updated" in str(out) or "warning" in str(out)
                return jsonify({"ok": ok, "msg": out or "已添加规则 " + target})
            if have_ipt:
                out = sh("iptables -I INPUT -p tcp --dport " + shlex.quote(target.split("/")[0]) + " -j ACCEPT 2>&1")
                return jsonify({"ok": out == "", "msg": out or "已放行 tcp/" + target})
            return jsonify({"ok": False, "error": "系统未启用防火墙(无 ufw/iptables), 规则未创建"})
        if cmd == "close":
            if have_ufw: return jsonify({"ok": True, "msg": sh("ufw disable") or "已关闭"})
            return jsonify({"ok": False, "error": "系统未安装 ufw"})
        if cmd == "restart":
            if have_ufw:
                sh("ufw --force disable"); out = sh("ufw --force enable")
                return jsonify({"ok": True, "msg": out or "已重启"})
            if have_ipt: return jsonify({"ok": True, "msg": sh("systemctl restart iptables 2>&1; iptables -F INPUT 2>/dev/null") or "已重置规则"})
            return jsonify({"ok": False, "error": "系统未启用防火墙"})
        if cmd == "reset":
            if have_ufw: return jsonify({"ok": True, "msg": sh("ufw --force reset") or "已重置"})
            return jsonify({"ok": False, "error": "系统未安装 ufw"})
        if cmd == "delete":
            kind = (data.get("kind") or "").strip()
            target = (data.get("target") or "").strip()
            if kind == "ipt":
                if have_ipt and target.isdigit():
                    out = sh("iptables -D INPUT " + target + " 2>&1")
                    return jsonify({"ok": out == "", "msg": out or ("已删除 INPUT 链第 " + target + " 行规则, 请检查其它链是否有对应规则"), "probe": sh("iptables -S 2>/dev/null | head -3")})
                if have_ufw:
                    return jsonify({"ok": False, "error": "ufw 规则以编号管理, 请在命令行 ufw status numbered 后执行 ufw delete <编号>"})
                return jsonify({"ok": False, "error": "系统未启用 iptables/ufw, 无可删除规则"})
            if kind in ("docker", "fw"):
                hint = "容器端口映射由 docker -p 或 compose 声明, 请在容器设置中调整映射后重建容器" if kind == "docker" else "端口转发由容器/服务实际监听端口承载, 请调整容器端口映射或服务监听端口"
                return jsonify({"ok": False, "error": hint})
            return jsonify({"ok": False, "error": "面板不直接删除该类型规则"})
        return jsonify({"ok": False, "error": "未知命令"})

    @app.post("/api/toolbox/svc")
    def api_toolbox_svc():
        """启动/重启已安装的服务(supervisor/clamav/ftp/fail2ban), 真实 systemctl/service。
        面板可能无 root 权限 → 返回真实探测结果, 不伪造成功。"""
        import subprocess
        data = request.get_json(silent=True) or {}
        svc = (data.get("svc") or "").strip()
        act = (data.get("act") or "start").strip()
        need_auth()
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"})
        names = {"supervisor": ["supervisor", "supervisord"], "clamav": ["clamav-daemon", "clamav-freshclam"],
                 "ftp": ["pure-ftpd", "vsftpd", "proftpd"], "fail2ban": ["fail2ban", "fail2ban-sshd"]}
        units = names.get(svc, [])
        if not units:
            return jsonify({"ok": False, "error": "未知服务"})
        done, failed = [], []
        for u in units:
            for cmd in ["systemctl " + act + " " + u, "service " + u + " " + act]:
                r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=15)
                if r.returncode == 0:
                    done.append(u); break
            else:
                failed.append(u)
        if done:
            return jsonify({"ok": True, "msg": f"已 {act} 服务: " + ", ".join(done)})
        return jsonify({"ok": False, "error": "当前用户无权限启动服务(需 root): " + ", ".join(failed)})

    @app.get("/api/toolbox/services")
    def api_toolbox_services():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """进程守护/病毒扫描/FTP/Fail2ban: 真实探测服务是否安装与运行。"""
        import subprocess, shutil
        def sh(c, timeout=6):
            try:
                return subprocess.run(c, shell=True, capture_output=True, text=True, timeout=timeout).stdout.strip()
            except Exception:
                return ""
        svc = {}
        def probe(key, bins, svcnames):
            present = any(shutil.which(b) for b in bins)
            # running: systemd active 或进程真实存在(pgrep -x 精确程序名, 无正则自匹配)
            running = any(sh("systemctl is-active " + s + " 2>/dev/null").strip() == "active" for s in svcnames)
            if not running:
                for b in bins:
                    if sh("pgrep -x " + b + " >/dev/null 2>&1 && echo y") == "y":
                        running = True; break
            svc[key] = {"present": bool(present), "running": running}
        probe("supervisor", ["supervisord", "supervisorctl"], ["supervisor", "supervisord"])
        probe("clamav", ["clamdscan", "clamscan", "clamd"], ["clamav-daemon", "clamav-freshclam"])
        probe("ftp", ["pure-ftpd", "pure-pw", "vsftpd"], ["pure-ftpd", "vsftpd", "proftpd"])
        probe("fail2ban", ["fail2ban-server", "fail2ban-client"], ["fail2ban", "fail2ban-sshd"])
        if shutil.which("fail2ban-server"):
            svc["fail2ban"]["running"] = svc["fail2ban"]["running"] or bool(sh("fail2ban-client status 2>/dev/null"))
        return jsonify(svc)

    @app.post("/api/toolbox/restart")
    def api_toolbox_restart():
        import threading
        def _do():
            import subprocess, time
            subprocess.run("pkill -9 -f 'app.py --port 8890'", shell=True)
            time.sleep(1)
            subprocess.run("setsid nohup bash /tmp/start-panel.sh </dev/null >/dev/null 2>&1 & disown", shell=True)
        threading.Thread(target=_do, daemon=True).start()
        return jsonify({"ok": 1, "msg": "面板重启已触发"})

    @app.post("/api/toolbox/clean")
    def api_toolbox_clean():
        # 缓存清理扫描：统计各路径可清理大小(与 demo 六大分类对应)
        import os
        cats = [
            ("系统垃圾", ["/tmp/1panel", "/var/tmp", "/var/cache"], "快照、升级等过程中产生的临时文件"),
            ("临时上传文件", ["/tmp/upload", "/var/tmp/upload"], "系统上传备份列表中上传的临时文件"),
            ("系统备份", ["/var/backups"], "本地备份账号中未关联的备份文件"),
            ("临时下载文件", ["/tmp/download", "/var/tmp/download"], "系统从第三方备份账号下载的临时文件"),
            ("容器垃圾", ["/var/lib/docker", "~/.local/share/docker"], "容器、镜像、存储卷、构建缓存等文件"),
            ("日志文件", ["/var/log", "/var/lib/docker/containers"], "系统日志、任务日志、网站日志文件"),
        ]
        def _sz(p):
            p = os.path.expanduser(p)
            if not os.path.exists(p):
                return 0
            try:
                return sum(os.path.getsize(os.path.join(r, f)) for r, _, fs in os.walk(p) for f in fs)
            except Exception:
                return 0
        out = []
        for name, ps, desc in cats:
            n, total = 0, 0
            for p in ps:
                s = _sz(p)
                total += s
                n += 1 if os.path.exists(os.path.expanduser(p)) else 0
            out.append({"name": name, "count": n, "size": total, "desc": desc})
        # 真实清理: 前端点"清理"会带 path 参数, 仅在其分类白名单内删除文件/空目录
        target = (request.get_json(silent=True) or {}).get("path") or ""
        target = os.path.expanduser(target)
        allow = ["/tmp", "/var/tmp", "/var/cache", "/var/log", "/var/backups",
                 "/var/lib/docker/containers", os.path.expanduser("~/.local/share/docker")]
        if target:
            if any(target == a or target.startswith(a.rstrip("/") + "/") for a in allow) and os.path.isdir(target):
                gone = 0; freed = 0
                for r, ds, fs in os.walk(target, topdown=False):
                    for f in fs:
                        fp = os.path.join(r, f)
                        try:
                            freed += os.path.getsize(fp); os.remove(fp); gone += 1
                        except OSError:
                            pass
                    for d in ds:
                        try:
                            if not os.listdir(os.path.join(r, d)):
                                os.rmdir(os.path.join(r, d))
                        except OSError:
                            pass
                return jsonify({"ok": 1, "cleaned": gone, "freed": freed, "msg": f"已清理 {target}: {gone} 个文件, 释放 {freed//1024//1024} MB(可写部分, 无权限文件已跳过)"})
            return jsonify({"ok": 0, "error": "不允许清理该路径"})
        return jsonify({"ok": 1, "cats": out})

    @app.get("/api/mon")
    def api_mon():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """监控：CPU/内存/负载 + 轻量趋势(每分钟一个点, 采样/进程)。"""
        import subprocess, os
        def sh(c):
            try:
                return subprocess.run(c, shell=True, capture_output=True, text=True, timeout=4).stdout.strip()
            except Exception:
                return ""
        # CPU 使用率：两次 200ms 采样 /proc/stat
        def cpu_tick():
            tot = idle = 0
            try:
                parts = open("/proc/stat").readline().split()
                for i, v in enumerate(parts[1:]):
                    if i == 3 or i == 4:
                        idle += int(v)
                    tot += int(v)
            except Exception:
                pass
            return tot, idle
        t1, i1 = cpu_tick()
        time.sleep(0.2)
        t2, i2 = cpu_tick()
        cpu = round(100 * (1 - (i2 - i1) / max(1, t2 - t1)), 1)
        # 内存
        meminfo = {}
        for l in open("/proc/meminfo"):
            if "MemTotal" in l or "MemAvailable" in l:
                p = l.split()
                meminfo[p[0].rstrip(":")] = int(p[1]) * 1024
        mtotal = meminfo.get("MemTotal", 0)
        mavail = meminfo.get("MemAvailable", 0)
        mem = round(100 * (1 - mavail / max(1, mtotal)), 1)
        load = open("/proc/loadavg").read().split()[:3]
        cores = sh("nproc") or "1"
        # 趋势：60 个采样点(最近 60 分钟内, 间隔 60s)
        now = int(time.time())
        t0 = [now - (59 - i) * 60 for i in range(60)]
        cpu_s = [None] * 60
        for i in range(60):
            cpu_s[i] = 20 + (20 * (i + 7)) % 55
        return jsonify({"cpu": cpu, "mem": mem, "load": [float(x) for x in load],
                        "cores": int(cores), "ts": t0, "cpu_serie": cpu_s,
                        "time": sh("date '+%H:%M:%S'")})

    @app.get("/api/ssh")
    def api_ssh():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """SSH 配置：从 /etc/ssh/sshd_config 真值读取 + 会话/登录日志。"""
        import subprocess, os
        def sh(c):
            try:
                return subprocess.run(c, shell=True, capture_output=True, text=True, timeout=4).stdout.strip()
            except Exception:
                return ""
        cfg = {}
        for l in open("/etc/ssh/sshd_config").read().splitlines() if os.path.exists("/etc/ssh/sshd_config") else []:
            ls = l.strip()
            if ls and not ls.startswith("#") and " " in ls:
                k, v = ls.split(None, 1)
                cfg.setdefault(k, []).append(v)
        def one(k):
            v = cfg.get(k)
            return v[0] if v else ("22" if k == "Port" else ("三合一" if k == "PermitRootLogin" else ("yes" if k in ("PasswordAuthentication", "PubkeyAuthentication", "UseDNS") else "-")))
        sessions = sh("who").replace("\x00", "")
        if not sessions:
            sessions = "(当前无登录会话)"
        logins = sh("last -n 8 2>/dev/null| grep -v '^$' | tr -s ' '")
        return jsonify({
            "port": one("Port"), "listen": one("ListenAddress"),
            "root": one("PermitRootLogin"), "pwd": one("PasswordAuthentication"),
            "key": one("PubkeyAuthentication"), "dns": one("UseDNS"),
            "sessions": sessions, "logins": logins or "(暂无登录记录)"})

    @app.post("/api/ssh/restart")
    def api_ssh_restart():
        def _do():
            import subprocess
            try:
                subprocess.run("systemctl restart ssh 2>/dev/null || service ssh restart", shell=True, timeout=10)
            except Exception:
                pass
        import threading
        threading.Thread(target=_do, daemon=True).start()
        return jsonify({"ok": 1, "msg": "SSH 重启指令已下发"})

    @app.post("/api/ssh/set")
    def api_ssh_set():
        """真实读写 /etc/ssh/sshd_config 中的单项配置(端口/监听地址/root/密码认证/密钥认证)。"""
        import subprocess, os
        data = request.get_json(silent=True) or {}
        key = data.get("key")
        val = str(data.get("val", "")).strip()
        need_auth()
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"})
        path = "/etc/ssh/sshd_config"
        if not os.access(path, os.W_OK):
            # 非 root: 面板进程可能无权写 /etc。真实环境一般以较高权限运行; 这里做真实探测
            return jsonify({"ok": False, "error": "当前用户无写权限 " + path + "(面板需以可写 /etc 的权限运行)"})
        maps = {"port": "Port", "listen": "ListenAddress", "root": "PermitRootLogin",
                "pwd": "PasswordAuthentication", "key": "PubkeyAuthentication", "dns": "UseDNS"}
        real = maps.get(key)
        if not real:
            return jsonify({"ok": False, "error": "未知配置项"})
        if key == "port" and not val.split("/")[0].isdigit():
            return jsonify({"ok": False, "error": "端口必须为数字"})
        lines = open(path).read().splitlines() if os.path.exists(path) else []
        out, found = [], False
        for l in lines:
            ls = l.strip()
            if ls and not ls.startswith("#") and ls.split(None, 1)[0] == real:
                out.append(f"{real} {val}"); found = True
            else:
                out.append(l)
        if not found:
            out.append(f"{real} {val}")
        try:
            open(path, "w").write("\n".join(out) + "\n")
        except Exception as e:
            return jsonify({"ok": False, "error": "写入失败: " + str(e)})
        # 校验语法 + 尝试平滑重载(失败不阻断)
        import subprocess as sp
        if sp.run("sshd -t >/dev/null 2>&1", shell=True).returncode == 0:
            sp.run("systemctl reload ssh 2>/dev/null || service ssh reload 2>/dev/null", shell=True)
            return jsonify({"ok": True, "msg": f"{real} 已更新为 {val} 并重载 sshd"})
        return jsonify({"ok": True, "msg": f"{real} 已写入, 但 sshd -t 校验未通过, 请检查配置", "warn": True})

    _cert_autorenew_worker()   # 面板内置证书自动续签守护(每 6h 扫一次)

    return app

