#term .term-tags{display:contents}
#term .term-tag{display:inline-flex;align-items:center;gap:4px;height:22px;padding:0 6px;border-radius:2px;background:var(--el-fill-color,#f0f2f5);color:var(--el-text-color-regular,#606266);font-size:12px}
