#term .tc-menu{position:fixed;z-index:4000;min-width:120px;background:var(--el-bg-color-overlay,#fff);border:1px solid var(--el-border-color-light,#e4e7ed);border-radius:4px;box-shadow:0 12px 32px 4px rgba(0,0,0,.04),0 8px 20px rgba(0,0,0,.08);padding:6px 0;font-size:14px}
